using JobOrbit.Application.Authorization;using JobOrbit.Application.DTOs.AdminJobs;using JobOrbit.Application.Interfaces;using JobOrbit.Domain.Enums;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace JobOrbit.API.Controllers;[ApiController,Route("api/admin/jobs"),Authorize(Roles=nameof(UserRole.Administrator)),Authorize(Policy=PermissionConstants.AdminJobsManage)]public sealed class AdminJobsController(IAdminJobService service):ControllerBase
{bool Id(out int id)=>int.TryParse(User.FindFirst("UserId")?.Value,out id);[HttpGet]public async Task<IActionResult>List([FromQuery]AdminJobQuery q,CancellationToken t){var x=await service.ListAsync(q,t);return x.Valid?Ok(x.Result):x.Error?.EndsWith("not found")==true?NotFound(new ProblemDetails{Status=404,Title=x.Error}):BadRequest(new ProblemDetails{Status=400,Title=x.Error});}[HttpGet("{jobId:int}")]public async Task<IActionResult>Details(int jobId,CancellationToken t)=>await service.DetailsAsync(jobId,t)is{}x?Ok(x):NotFound(new ProblemDetails{Status=404,Title="Job not found"});[HttpPut("{jobId:int}")]public async Task<IActionResult>Update(int jobId,UpdateAdminJobRequest r,CancellationToken t){if(!Id(out var id))return Unauthorized();return Result(await service.UpdateAsync(id,jobId,r,t));}[HttpPatch("{jobId:int}/status")]public async Task<IActionResult>Status(int jobId,UpdateAdminJobStatusRequest r,CancellationToken t){if(!Id(out var id))return Unauthorized();return Result(await service.StatusAsync(id,jobId,r,t));}[HttpPatch("{jobId:int}/feature")]public async Task<IActionResult>Feature(int jobId,UpdateAdminJobFeaturedRequest r,CancellationToken t){if(!Id(out var id))return Unauthorized();return Result(await service.FeatureAsync(id,jobId,r,t));}IActionResult Result(AdminJobResult x)=>x.Outcome switch{AdminJobOutcome.Success=>Ok(x.Job),AdminJobOutcome.NotFound=>NotFound(new ProblemDetails{Status=404,Title="Job not found"}),AdminJobOutcome.InvalidStatus=>BadRequest(new ProblemDetails{Status=400,Title="Invalid job status"}),AdminJobOutcome.InactiveOwnership=>Conflict(new ProblemDetails{Status=409,Title="Organization, department, and recruiter must be active"}),AdminJobOutcome.Expired=>Conflict(new ProblemDetails{Status=409,Title="Closing date must be in the future"}),AdminJobOutcome.FeatureRequiresPublished=>Conflict(new ProblemDetails{Status=409,Title="Only active published jobs can be featured"}),_=>Conflict(new ProblemDetails{Status=409,Title="Invalid job status transition"})};}
